import {h,icon,button as btn,spoken} from './ui.mjs';
import {pronunciationGuides} from './pronunciation-data.mjs';

export function renderPronunciation(){
 return `<div class="page-heading"><div><h1>Слышать. Повторять. Сравнивать.</h1><p>Одна особенность за раз: звук, ударение или ритм фразы.</p></div></div><div class="notice">${icon('sound')}<span>Озвучка использует установленный датский голос. Для живой речи дополнительно слушай разных датчан; синтезатор не передаёт все разговорные особенности.</span></div><p class="field-note"><a href="https://ordnet.dk/ddo" target="_blank" rel="noopener noreferrer">Den Danske Ordbog · словарь с записями носителей</a></p><div class="pronunciation-grid">${pronunciationGuides.map(g=>`<article class="panel pronunciation-card"><span class="eyebrow">${h(g.focus)}</span><h2>${h(g.title)}</h2><p>${h(g.note)}</p><div class="pronunciation-words">${g.words.map(w=>`<div>${spoken(w.da)}<small>${h(w.ru)}</small></div>`).join('')}</div>${btn(`Практика ${icon('arrow')}`,'pronunciation-guide','secondary',`data-id="${h(g.id)}"`)}</article>`).join('')}</div>`;
}
export function recordingControls(recording){
 const busy=['requesting','recording','stopping'].includes(recording.phase);
 return `<div class="button-row">${recording.phase==='recording'?btn('Остановить','record-stop','primary'):btn(recording.url?'Записать ещё раз':'Записать себя','record-start','primary',busy?'disabled':'')}${recording.url?btn('Удалить запись','record-clear','secondary'):''}</div><p role="status" class="field-note">${h(recording.message||'Запись до 20 секунд. Она остаётся в памяти этой вкладки и удаляется при закрытии окна.')}</p>${recording.url?`<audio controls preload="metadata" src="${h(recording.url)}" aria-label="Твоя запись"></audio><p class="field-note">Сравни запись и образец. Автоматической оценки произношения нет.</p>`:''}`;
}
export function pronunciationCoach(text,guide,recording){
 const chunks=guide?.chunks||[];
 return `<div class="pronunciation-coach"><p class="coach-target" lang="da" data-audio-ready>${h(text)}</p>${guide?`<p>${h(guide.phraseRu)}</p><div class="note-box"><p>${h(guide.note)}</p></div>`:''}<div class="button-row">${btn(`${icon('sound')} Обычная скорость`,'coach-listen','secondary',`data-text="${h(text)}" data-value="1"`)}${btn(`${icon('sound')} Медленно`,'coach-listen','secondary',`data-text="${h(text)}" data-value="0.7"`)}</div>${chunks.length?`<h3>По частям, затем целиком</h3><div class="coach-chunks">${chunks.map((chunk,i)=>btn(`${i+1}. ${h(chunk)}`,'coach-listen','secondary',`data-text="${h(chunk)}" data-value="0.85" lang="da"`)).join('')}</div>`:''}<p class="field-note">Послушай целиком. Повтори несколько раз, затем запиши без одновременной озвучки.</p><div id="recording-controls">${recordingControls(recording)}</div><p class="field-note"><a href="https://ordnet.dk/ddo" target="_blank" rel="noopener noreferrer">Свериться с записью носителя в DDO</a></p><fieldset class="coach-checks"><legend>Проверь себя на слух</legend>${(guide?.checkpoints||['Сохранил ли я ударение в ключевых словах?','Слышны ли окончания и различия гласных?','Получается ли произнести фразу целиком без чтения по словам?']).map(t=>`<label><input type="checkbox">${h(t)}</label>`).join('')}</fieldset><p class="field-note">Эти отметки — твоя самопроверка. Они не прибавляют XP и не подтверждают запоминание слова.</p></div>`;
}
